   setProgress('Detecting components…');await new Promise(r=>setTimeout(r,30));
   const det=detectShapes(pixelsOf(page.canvas),{exclude:labels});const shapes=labelShapes(det.shapes,labels,.09,det.board);
   const textNote=page.kind==='pdf'&&!page.textItems.length?'PDF has no selectable text, so components are unnamed. Connect Claude vision in Integrations or export the PDF with text.':'';
   model=buildImageBoard({shapes,board:det.board,labels,widthMm,fileName:file.name,source,detector:'local',notes:[det.notes,textNote].filter(Boolean).join(' · ')});
   if(textNote)notify(textNote);
