 async function exportExcel(rows=filtered,template=false,bomTemplate=false){setBusy(true);try{const {default:ExcelJS}=await import('exceljs');const wb=new ExcelJS.Workbook();wb.creator='semi-cobot';const ws=wb.addWorksheet(template?'Import template':'Component directory');ws.columns=[{header:'MPN',key:'mpn',width:28},{header:'Manufacturer',key:'manufacturer',width:24},{header:'Category',key:'category',width:22},{header:'Description',key:'description',width:52},{header:'Package',key:'package',width:16},{header:'Stock',key:'stock',width:14},{header:'Minimum stock',key:'min',width:18},{header:'Unit price USD',key:'price',width:18},{header:'Lifecycle',key:'lifecycle',width:18},{header:'Location',key:'location',width:16},{header:'Data source',key:'source',width:24}];if(bomTemplate)ws.columns=[{header:'Reference',key:'refs',width:16},...ws.columns.map(c=>({header:c.header,key:c.key,width:c.width})),{header:'Quantity',key:'required',width:14}];rows.forEach(p=>ws.addRow({...p,source:p.source||'Sample data'}));if(bomTemplate)[{refs:'U1',mpn:'STM32F407VGT6',manufacturer:'STMicroelectronics',category:'Microcontrollers',description:'ARM Cortex-M4 MCU',package:'LQFP-100',required:1},{refs:'C1, C2, C3',mpn:'GRM188R71C104KA01D',manufacturer:'Murata',category:'Capacitors',description:'100 nF 0603',package:'0603',required:3},{refs:'D1',mpn:'SS14',manufacturer:'Diodes Incorporated',category:'Diodes',description:'Schottky 40 V 1 A',package:'SMA',required:1}].forEach(r=>ws.addRow(r));ws.getRow(1).font={bold:true,color:{argb:'FFFFFFFF'}};ws.getRow(1).fill={type:'pattern',pattern:'solid',fgColor:{argb:'FF163D36'}};ws.getRow(1).height=28;ws.views=[{state:'frozen',ySplit:1}];ws.autoFilter='A1:K1';ws.getColumn('price').numFmt='"$"0.00';ws.getColumn('stock').numFmt='#,##0';const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([await wb.xlsx.writeBuffer()],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}));a.download=template?'semi-cobot-import-template.xlsx':'semi-cobot-component-directory.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);notify('Excel file exported.')}catch{notify('Export failed. Try again.')}finally{setBusy(false)}}
 async function importExcel(file,isBom=false){if(!file)return;setBusy(true);try{if(file.size>5e6)throw Error('Choose a file smaller than 5 MB.');const{default:ExcelJS}=await import('exceljs');const wb=new ExcelJS.Workbook();await wb.xlsx.load(await file.arrayBuffer());const ws=wb.worksheets[0];if(!ws)throw Error('No worksheet found.');const headers=ws.getRow(1).values.map(v=>String(v||'').trim().toLowerCase());const mpnCol=headers.indexOf('mpn');if(mpnCol<1)throw Error('First row needs an MPN column. Download the template.');const rows=[];ws.eachRow((r,i)=>{if(i===1)return;const cell=h=>{const index=headers.indexOf(h);return index<1?'':r.getCell(index).text.trim()};const mpn=cell('mpn');if(!mpn)return;const numeric=(h,def=0)=>{const raw=cell(h);const value=raw===''?def:Number(raw);if(!Number.isFinite(value)||value<0)throw Error(`Row ${i}: ${h} must be a nonnegative number.`);return value};rows.push({id:crypto.randomUUID(),mpn,manufacturer:cell('manufacturer')||'Unspecified',category:cell('category')||'Uncategorized',description:cell('description')||'Imported component',package:cell('package')||'Unspecified',stock:numeric('stock'),min:numeric('minimum stock'),price:numeric('unit price usd'),lifecycle:cell('lifecycle')||'Unknown',location:cell('location')||'Unassigned',source:'Imported inventory',supplier:'Unassigned',specs:{},required:numeric('quantity',1),refs:cell('reference')||cell('references')||cell('designator')||cell('designators')||cell('refdes')||cell('ref')});});if(!rows.length)throw Error('No component rows found.');if(rows.length>3000)throw Error('Import up to 3,000 rows at a time.');if(isBom){setBom(rows);const map={};rows.forEach(r=>String(r.refs||'').split(/[\s,;]+/).filter(Boolean).forEach(ref=>{map[ref.toUpperCase()]=r.mpn}));const linked=Object.keys(map).length;if(linked)setBomMaps(prev=>({...prev,[board.id]:{...(prev[board.id]||{}),...map}}));notify(linked?`${rows.length} BOM lines · ${linked} references named on ${board.name}.`:`${rows.length} BOM lines imported.`)}else{setParts(prev=>{const map=new Map(prev.map(p=>[p.mpn.toUpperCase(),p]));rows.forEach(p=>map.set(p.mpn.toUpperCase(),{...map.get(p.mpn.toUpperCase()),...p,id:map.get(p.mpn.toUpperCase())?.id||p.id}));return [...map.values()]});notify(`${rows.length} components imported.`)}setModal(null)}catch(e){notify(e.message||'Could not read workbook. Use an .xlsx file.')}finally{setBusy(false)}}

