const initials=u=>u?.name?u.name.split(/\s+/).filter(Boolean).slice(0,2).map(w=>w[0].toUpperCase()).join(''):'SC';
// Front door: the intro page with the admin panel until someone is signed in. Without the local
// server (or in the Worker) sign-in is off and the intro opens the workspace for this tab.
function Root(){
 const [auth,setAuth]=useState(null),[opened,setOpened]=useState(()=>{try{return sessionStorage.getItem('semicobot-open')==='1'}catch{return false}});
 useEffect(()=>{fetch('/api/auth/state').then(r=>r.ok?r.json():null).catch(()=>null).then(j=>setAuth(j||{enabled:false,admin:false,user:null}))},[]);
 // A session that expires mid-use sends the next API call a 401: back to the sign-in.
 useEffect(()=>{const real=window.fetch;window.fetch=async(...a)=>{const r=await real(...a);const url=String(a[0]?.url||a[0]);if(r.status===401&&/^\/api\/(?!auth\/)/.test(url.replace(location.origin,'')))setAuth(x=>x?.user?{...x,user:null}:x);return r};return()=>{window.fetch=real}},[]);
 if(!auth)return <div className="intro-loading" aria-busy="true"/>;
 if(!(auth.enabled?auth.user:opened))return <Intro auth={auth} onSignedIn={user=>setAuth(a=>({...a,admin:true,user}))} onOpen={()=>{try{sessionStorage.setItem('semicobot-open','1')}catch{}setOpened(true)}}/>;
 return <App user={auth.user} onSignOut={auth.enabled?async()=>{await fetch('/api/auth/logout',{method:'POST'}).catch(()=>{});setAuth(a=>({...a,user:null}))}:null}/>;
}
createRoot(document.getElementById('root')).render(<Root/>);
